-- Smart Bike Rental App - Milestone 2
-- 03_seed_data.sql
-- Run AFTER 01_create_tables.sql on an empty database.
-- IDs are generated by SERIAL in insert order (1, 2, 3, ...), so the
-- foreign key values below rely on this file running once on empty tables.
-- Password hashes are fake placeholders, not real credentials.

-- users: 1 = admin, 2 = company, 3-5 = riders

-- payment_methods: one card per rider (users 3, 4, 5)

-- stations: created by the admin (user 1)

-- bikes: bike 5 is out on a ride (no station), bike 4 is broken

-- rentals: two completed rides and one active ride

-- rental_pauses: rental 1 had one pause, rental 3 is currently paused once

-- reservations: Sara reserved bike 2 for 15 minutes

-- pricing_plans: set by the admin (user 1)

-- promo_codes: issued by the admin (user 1)

-- payments: rental 1 used a promo code, rental 2 did not (rental 3 is still active)

-- damage_reports: Omar reported bike 4, Sara reported bike 2

-- maintenance_tickets: one from a damage report, one from a low-battery alert (no report)

-- geofence_zones: defined by company staff (user 2)

-- disputes: one approved, one still open

-- sos_events: Ali pressed SOS during his active ride
